// What the app can do with no internet: the app itself and the receipt reader are
// saved by the service worker (public sw.js generated by scripts/offline.ts).

import { useEffect, useState } from 'react';

export function useOnline(): boolean {
  const [online, setOnline] = useState(navigator.onLine);
  useEffect(() => {
    const on = () => setOnline(navigator.onLine);
    window.addEventListener('online', on);
    window.addEventListener('offline', on);
    return () => { window.removeEventListener('online', on); window.removeEventListener('offline', on); };
  }, []);
  return online;
}

export interface OfflineStatus { appReady: boolean; ocrReady: boolean }

/** null while checking or when the browser has no service worker (e.g. during development). */
export function useOfflineStatus(): OfflineStatus | null {
  const [status, setStatus] = useState<OfflineStatus | null>(null);
  const online = useOnline();
  useEffect(() => {
    if (!('serviceWorker' in navigator)) return;
    let t: ReturnType<typeof setInterval> | undefined;
    const onMsg = (e: MessageEvent) => {
      if (e.data?.type !== 'status') return;
      setStatus({ appReady: e.data.appReady, ocrReady: e.data.ocrReady });
      if (e.data.appReady && e.data.ocrReady) clearInterval(t);
    };
    navigator.serviceWorker.addEventListener('message', onMsg);
    const ask = () => navigator.serviceWorker.ready.then((r) => r.active?.postMessage('status'));
    ask();
    t = setInterval(ask, 4000);
    return () => { clearInterval(t); navigator.serviceWorker.removeEventListener('message', onMsg); };
  }, [online]);
  return status;
}
